draw(Circle((0,0),25/8));
draw(((-3,-7/8)--(3,-7/8)--(0,25/8)--cycle));
dot((0,0));
draw(((0,25/8)--(0,0)),dotted);
draw(((0,-5/8)--(-1/4,-5/8)--(-1/4,-7/8)));
label("5",(-3/2,9/8),NW);
label("5",(3/2,9/8),NE);
draw(((0,0)--(0,-9/8)));
label("3",(-3/2,-7/8),S);
label("3",(3/2,-7/8),S);
label("$r$",(0,5/4),E);
label("$4-r$",(0,-7/16),E);
draw(((0,0)--(-3,-7/8)--(0,-7/8)--cycle),black+1.5);
